import http from 'k6/http';
import { check, fail } from 'k6';

export const options = {
  vus: 1,
  iterations: 1,
  thresholds: {
    checks: ['rate==1.0'],
    http_req_failed: ['rate==0'],
  },
};

const BASE_URL = (__ENV.BASE_URL || '').replace(/\/+$/, '');

function ensureOk(res, name) {
  const ok = check(res, {
    [`${name} status is 2xx`]: (r) => r.status >= 200 && r.status < 300,
  });
  if (!ok) {
    fail(`${name} failed with status ${res.status}: ${res.body}`);
  }
}

export default function () {
  if (!BASE_URL) {
    fail('BASE_URL environment variable is required');
  }

  // Per-VU cookie jar is used automatically by k6.
  const jsonHeaders = { 'Content-Type': 'application/json' };

  // 1. Login
  const loginRes = http.post(
    `${BASE_URL}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: jsonHeaders, tags: { name: 'login' } }
  );
  ensureOk(loginRes, 'login');

  let csrf;
  try {
    csrf = loginRes.json('csrf');
  } catch (e) {
    fail(`login response is not valid JSON: ${loginRes.body}`);
  }
  const hasToken = check(csrf, {
    'csrf token extracted': (t) => typeof t === 'string' && t.length > 0,
  });
  if (!hasToken) {
    fail('csrf token missing from login response');
  }

  const csrfHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };

  // 2. Product listing
  const productsRes = http.get(`${BASE_URL}/products`, {
    tags: { name: 'products' },
  });
  ensureOk(productsRes, 'products');

  // 3. Add to cart
  const cartRes = http.post(
    `${BASE_URL}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    { headers: csrfHeaders, tags: { name: 'cart' } }
  );
  ensureOk(cartRes, 'cart');

  // 4. Checkout (exactly once per session)
  const checkoutRes = http.post(`${BASE_URL}/checkout`, JSON.stringify({}), {
    headers: csrfHeaders,
    tags: { name: 'checkout' },
  });
  ensureOk(checkoutRes, 'checkout');
}
